<script setup lang="ts">
import {useI18n} from 'vue-i18n'
import type {PayItem} from '../payrollTypes'
defineProps<{items:PayItem[];month:string}>()
const {locale}=useI18n(),x=(z:string,e:string)=>locale.value.startsWith('en')?e:z,business=(v:string)=>v==='leave_encashment'?x('未休年假折现','Unused annual leave encashment'):v==='bonus'?x('奖金','Bonus'):v==='aws'?x('年度工资补贴（AWS）','Annual Wage Supplement (AWS)'):v==='retroactive_increment'?x('追溯加薪','Retroactive increment'):v==='omitted_wages'?x('原已到期遗漏工资','Originally due omitted wages'):v
</script>
<template><section v-if="items.some(i=>i.kind==='wage_event')" class="wf-section"><h4>{{month}} · {{x('待审批工资事项凭证','Wage event evidence for review')}}</h4><article v-for="(item,index) in items.filter(i=>i.kind==='wage_event')" :key="item.itemId||index"><h5>{{item.label}} · SGD {{item.amount}}</h5><dl v-if="item.eventEvidence" class="wf-details"><dt>{{x('业务类别／法定分类','Business category / statutory class')}}</dt><dd>{{business(item.eventEvidence.businessType)}} · {{item.eventEvidence.classification}}</dd><dt>{{x('事项编号','Event ID')}}</dt><dd>{{item.eventEvidence.eventId}}</dd><dt>{{x('服务期','Service period')}}</dt><dd>{{item.eventEvidence.serviceFrom}} – {{item.eventEvidence.serviceTo}}</dd><dt>{{x('决定日期／合同应付日期','Decision date / contractual payable date')}}</dt><dd>{{item.eventEvidence.decisionDate||'—'}} / {{item.eventEvidence.contractualPayableDate}}</dd><dt>{{x('贡献月／结算月','Contribution / settlement month')}}</dt><dd>{{item.eventEvidence.contributionMonth}} / {{item.eventEvidence.settlementMonth}}</dd><dt>{{x('合同／批准凭证','Contract / approval evidence')}}</dt><dd>{{item.eventEvidence.evidenceReference||x('缺失','Missing')}}</dd><dt>{{x('分类理由','Classification reason')}}</dt><dd>{{item.eventEvidence.classificationReason||x('缺失','Missing')}}</dd></dl><p v-else class="wf-issue" role="alert">{{x('缺少事项分类凭证，不能认定为可计薪。','Event evidence is missing; payable wages cannot be established.')}}</p></article></section></template>
<style scoped>dd{overflow-wrap:anywhere;white-space:pre-wrap}h5{font-size:inherit}</style>
